function render(){const content={home:homePage,world:worldPage,builder:builderPage,logic:logicPage,labs:labsPage,journal:journalPage,pulse:pulsePage,quests:questsPage,studios:studiosPage,orbit:orbitPage,vault:vaultPage,library:libraryPage,fieldguide:fieldGuidePage,team:teamPage,parent:parentPage,settings:settingsPage}[route];const contentHtml=content();const extraHtml=realRouteExtras();const combined=route==='team'?contentHtml.replace('<div class="section-titlebar">', extraHtml+'<div class="section-titlebar">'):contentHtml+extraHtml;$('#view').innerHTML=`<div class="page">${combined}</div>`;if(route==='builder')setupCanvas();if(route==='orbit')$('#chat-messages')?.scrollTo(0,99999);}
function missionTile(q){return `<button class="mission-tile" data-quest="${esc(q.id)}"><span class="tag tag-gold">${esc(q.category)}</span><span class="icon-xl" aria-hidden="true">${esc(q.emoji||'✦')}</span><h3>${esc(q.title)}</h3><p>${esc(q.description)}</p><span class="mission-tile-foot"><span>${esc(q.level||'Explorer')} · ${esc(q.duration||'Self-paced')}</span><b>START QUEST ↗</b></span></button>`}
function homePage(){const p=P[profile];const pq=questProgress(),complete=Object.values(pq).filter(Boolean).length,projects=allProjects().length;const featured=['sky-fortress','robot-rescue','mars-colony'].map(findQuest).filter(Boolean);return `<div class="hub-heading"><div><div class="eyebrow">CHAPTER 01 <span class="tiny-divider">/</span> YOUR STORY STARTS HERE</div><h1>Welcome back, <strong>${esc(p.name)}.</strong></h1><p>${esc(p.motif)} Your next discovery is closer than you think.</p></div><div class="right-meta"><span class="tag tag-lime">✳ LOCAL WORKSPACE</span><button class="btn btn-outline" data-action="new-project">${icon('plus')} NEW PROJECT</button></div></div><div class="home-grid"><div><article class="feature-hero"><div class="corner-cross">✦</div><div class="feature-copy"><div class="eyebrow">✦  THE FORGEVERSE IS CALLING</div><h2>THIS WORLD<br>WAS MADE<br><em>TO BE MADE.</em></h2><p>Explore impossible places. Learn real skills. Make extraordinary things with your own two hands.</p><div class="hero-buttons"><button class="btn btn-primary" data-route="world">EXPLORE FORGEVERSE ${icon('arrow')}</button><button class="btn btn-outline" data-route="builder">OPEN YOUR BUILDER ${icon('box')}</button></div></div><div class="hero-footer"><span>✦  WORLD 01 / THE AETHER CITADEL</span><span><b>◉</b> A WHOLE UNIVERSE OF IDEAS</span></div></article><div class="section-titlebar"><div><div class="eyebrow">YOUR NEXT ADVENTURES</div><h2>Choose a quest</h2></div><button data-route="quests">ALL ${getQuests().length} QUESTS ↗</button></div><div class="missions-home">${featured.map(missionTile).join('')||'<div class="surface" style="padding:30px">Loading missions…</div>'}</div><div class="home-bottom"><article class="surface co-op-home"><span class="eyebrow">✦  THE BROTHERHOOD CHALLENGE</span><h3>Better things happen together.</h3><p>One designs, one tests. Swap roles, challenge assumptions and build something neither of you could make alone.</p><button class="side-link" data-route="team">ENTER TEAM FORGE ${icon('arrow')}</button></article><article class="surface home-log"><div class="eyebrow">THE INVENTOR'S LOG</div><div class="log-stats"><strong>${complete}<small> / ${getQuests().length}</small></strong><small>QUESTS COMPLETED</small><strong>${projects}</strong><small>PROJECTS SAVED</small></div><div class="progress-track"><span style="width:${getQuests().length?complete/getQuests().length*100:0}%"></span></div><div style="font-size:11px;color:var(--muted)">Not a competition. Progress means trying, observing, and improving.</div></article></div></div><aside class="home-side"><article class="surface side-box"><div class="side-eyebrow">ACTIVE WORKSHOP</div><div class="identity-hero"><span class="identity-badge">${esc(p.initial)}</span><div><strong>${esc(p.name.toUpperCase())}</strong><small>${esc(p.role)}</small></div></div><div class="mini-divider"></div><div style="font-size:10px;color:var(--muted)">ONE DEVICE. PERSONAL IDEAS. SHARED ADVENTURES.</div><button class="side-link" data-action="switch-profile">SWITCH INVENTOR ${icon('arrow')}</button></article><article class="surface side-box orbit-card"><div class="orbit-head"><div class="side-eyebrow">YOUR INVENTION COMPANION</div><span class="tag">LOCAL AI OPTION</span></div>${orbitSculpture()}<h3>Meet ORBIT.</h3><p>Big question? Small experiment. I'll help you turn 'what if?' into 'what next?'.</p><button class="side-link" data-route="orbit">ASK SOMETHING AMAZING ${icon('arrow')}</button></article><article class="surface side-box"><div class="side-eyebrow">PICK UP WHERE YOU LEFT OFF</div><h3>${projects?'Your inventions':'A blank page is a beginning.'}</h3><p>${projects?'Your projects are waiting in the vault.':'Save a design, record a test, or give your next big idea a name.'}</p><button class="side-link" data-route="vault">OPEN PROJECT VAULT ${icon('arrow')}</button></article></aside></div>`}
function orbitSculpture(){return `<div class="orbit-sculpture" aria-hidden="true"><div class="orbit-ring"></div><div class="orbit-body"><div class="orbit-ear"></div><span class="orbit-eye">• •</span></div></div>`}
function worldPage(){const r=REGIONS[selectedRegion];const q=findQuest(r.mission);return `<div class="realm-intro"><div><div class="eyebrow">THE ATLAS OF IMPOSSIBLE PLACES / SIX FRONTIERS</div><h1>Every world<br><em>starts with wonder.</em></h1><p>Click a destination to choose your next quest. Each imaginary frontier is a doorway to genuine skills and experiments.</p></div><div class="tag tag-gold">CHAPTER 01 <span style="color:#f8f2df">/</span> THE AETHER CITADEL</div></div><div class="realm-main"><div class="world-canvas"><div class="map-overlay-lines"></div><span class="world-label">✦  FORGEVERSE / DISCOVERY ATLAS</span>${REGION_POINTS.map(([key,em,x,y])=>`<button class="map-point ${selectedRegion===key?'selected':''}" style="left:${x};top:${y}" data-region="${key}" aria-label="Explore ${esc(REGIONS[key].title)}"><i>${em}</i><span><strong>${esc(REGIONS[key].title.toUpperCase())}</strong><small>${esc(REGIONS[key].tag.split(' & ')[0].toLowerCase())}</small></span></button>`).join('')}<span class="world-coordinate">45° N / 80° W · COORDINATES ARE FICTIONAL · CONCEPT WORLD</span></div><aside class="surface region-panel"><div class="eyebrow">◉  REGION SELECTED</div><div class="region-top-image"></div><div class="tag tag-gold">${esc(r.tag)}</div><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><div class="region-facts"><div>SKILL FOCUS <b>${esc(r.fact)}</b></div><div>REGION STATUS <b>OPEN TO EXPLORE</b></div><div>MISSION <b>${esc(q?.title||'Select a quest')}</b></div></div><button class="btn btn-primary" data-quest="${esc(q?.id||'sky-fortress')}">EXPLORE THIS MISSION ${icon('arrow')}</button><button class="btn btn-outline" data-route="builder" style="margin-top:9px">BUILD SOMETHING HERE ${icon('box')}</button></aside></div><p class="disclosure">ForgeVerse is currently an interactive story map and mission selector, not a loaded 3D game. The planned Luanti world is a separate integration milestone. The locations and coordinates are fictional.</p>`}
function builderPage(){const cnt=Object.keys(blocks).length;return `${pagehead('BUILD LAB / VOXEL DESIGN','Pocket Builder.','Real block placement, eight construction layers, undo/redo and portable blueprints.',`<span class="tag tag-gold">${cnt} BLOCKS PLACED</span> <button class="btn btn-outline" data-action="builder-export">${icon('download')} EXPORT BLUEPRINT</button>`)}<div class="workshop-layout"><div class="workspace-stage"><div class="workspace-header"><div><strong>✦ THE ARCHITECT'S TABLE</strong><br><small>12 × 12 grid · eight vertical layers · 6 materials</small></div><span class="tag tag-lime">◉ LOCAL MODEL</span></div><div class="workspace-body"><div class="canvas-hint">VIEW ${fmtNum(angle+1)} / 04 &nbsp; · &nbsp; ${erase?'ERASE MODE':'PLACE MODE'} &nbsp; · &nbsp; LAYER ${layer+1} / 8</div><canvas id="build-canvas" width="1100" height="650" aria-label="Interactive isometric block construction area. Choose a material and click to place blocks."></canvas><div class="canvas-coordinates">X 00 → 11 <span class="tiny-divider">/</span> Y 00 → 11 <span class="tiny-divider">/</span> Z 00 → 07</div></div><div class="builder-foot"><span>Click the grid to ${erase?'erase':'place'} ${esc(MATERIALS.find(m=>m.id===material)?.name||'Moss').toLowerCase()} blocks on layer ${layer+1}.</span><span><b class="color-alert" id="builder-count">${cnt}</b> BLOCKS</span></div></div><aside class="builder-tools"><div class="surface tool-card"><div class="eyebrow">01 / MATERIALS</div><h3>Choose a substance.</h3><div class="material-grid">${MATERIALS.map(m=>`<button class="material-choice ${material===m.id?'active':''}" data-material="${m.id}"><span class="block-swatch" style="background:${m.hex}"></span>${m.name}</button>`).join('')}</div><p class="microtext">Materials are visual in this demo, not engineering simulations.</p></div><div class="surface tool-card"><div class="eyebrow">02 / BUILD CONTROLS</div><h3>Shape the blueprint.</h3><label for="level-range" style="display:block;font-size:11px;color:var(--muted);font-weight:800;margin:10px 0">BUILD LAYER <b id="level-out" style="color:var(--aqua)">${layer+1} / 8</b></label><input class="level-slider" id="level-range" type="range" min="0" max="7" value="${layer}"><div class="builder-button-grid"><button class="btn btn-outline" data-action="builder-rotate">${icon('rotate')} ROTATE</button><button class="btn btn-outline" data-action="builder-erase">${icon('box')} ${erase?'PLACE':'ERASE'}</button><button class="btn btn-outline" data-action="builder-undo">${icon('undo')} UNDO</button><button class="btn btn-outline" data-action="builder-redo">${icon('rotate')} REDO</button><button class="btn btn-outline" data-action="builder-demo">${icon('wand')} EXAMPLE</button><button class="btn btn-outline" data-action="builder-clear">${icon('close')} CLEAR</button></div><label class="btn btn-outline" style="width:100%;cursor:pointer">${icon('download')} IMPORT BLUEPRINT<input type="file" id="builder-import" accept="application/json,.json" hidden></label><div class="builder-safety">Each inventor's blueprint is stored separately in this browser. Team Forge uses its own shared prototype workspace. This does not enforce Linux file permissions.</div></div></aside></div>`}
function logicPage(){const complete=read(profileKey('logic-completed'),false);const arrows=logicCommands.map((c,i)=>`<span class="logic-instruction ${i<logicState.step?'done':''}"><b>${fmtNum(i+1)}</b>${LOGIC_LABELS[c]}</span>`).join('');const grid=Array.from({length:49},(_,idx)=>{const x=idx%7,y=Math.floor(idx/7),key=x+','+y;const isWall=LOGIC_WALLS.has(key),isGoal=x===6&&y===0,isPower=x===3&&y===3,isBot=x===logicState.x&&y===logicState.y;return`<div class="logic-cell ${isWall?'wall':''} ${isGoal?'goal':''} ${isPower?'power':''} ${isBot?'robot':''}" role="gridcell" aria-label="Grid ${x},${y} ${isWall?'wall':isBot?'robot':isGoal?'finish':isPower?'energy cell':'empty'}"><span>${isBot?'🤖':isGoal?'🏁':isPower?'⚡':''}</span></div>`}).join('');return `${pagehead('CODE QUEST / THE ROBOT LOGIC LAB','Think like a programmer.','Build a sequence of instructions, collect the energy crystal, and reach the flag.',`<span class="tag ${complete?'tag-lime':'tag-gold'}">${complete?'✓ MISSION SOLVED':'◉ LEARN SEQUENCING'}</span>`)}<div class="logic-layout"><article class="surface logic-arena"><div class="workspace-header"><div><strong>✦ THE CIRCUIT GARDEN</strong><br><small>7 × 7 navigation grid · plan your route · test your program</small></div><span class="tag tag-lime">NO INTERNET REQUIRED</span></div><div class="logic-arena-center"><div class="logic-grid" role="grid" aria-label="Robot coding puzzle">${grid}</div><div class="logic-overlay-hint">START AT LOWER LEFT → COLLECT ⚡ → REACH 🏁<br>AVOID THE DARK OBSTACLES</div></div><div class="logic-status"><span class="tag ${logicState.status==='SOLVED!'?'tag-lime':'tag-gold'}">${esc(logicState.status)}</span><span>POSITION X:${logicState.x} Y:${logicState.y} &nbsp; / &nbsp; ENERGY: ${logicState.energy?'COLLECTED':'NOT YET'}</span></div></article><aside class="logic-tools"><div class="surface tool-card"><div class="eyebrow">01 / WRITE A PROGRAM</div><h3>Tell the robot what to do.</h3><p style="font-size:12px;color:var(--muted)">Click arrows to add commands. The robot follows each instruction exactly, in order.</p><div class="logic-pad">${[['U','↑','UP'],['R','→','RIGHT'],['D','↓','DOWN'],['L','←','LEFT']].map(([key,glyph,word])=>`<button data-action="logic-add" data-cmd="${key}" aria-label="Add ${word} instruction"><b>${glyph}</b><small>${word}</small></button>`).join('')}</div><div class="eyebrow" style="margin-top:22px">YOUR CODE / ${logicCommands.length} COMMANDS</div><div class="logic-program">${arrows||'<span class="logic-placeholder">Your instruction blocks appear here.</span>'}</div><div class="builder-button-grid"><button class="btn btn-outline" data-action="logic-remove">${icon('undo')} REMOVE</button><button class="btn btn-outline" data-action="logic-clear">${icon('close')} CLEAR</button><button class="btn btn-outline" data-action="logic-reset">${icon('rotate')} RESET</button><button class="btn btn-outline" data-action="logic-step">${icon('play')} STEP</button></div><button class="btn btn-primary" data-action="logic-run" style="width:100%;margin-top:8px" ${logicRunning?'disabled':''}>${icon('play')} ${logicRunning?'RUNNING…':'RUN MY PROGRAM'}</button></div><div class="surface tool-card"><div class="eyebrow">02 / ENGINEER'S TIP</div><h3>Debug, don't guess.</h3><p style="font-size:12px;color:var(--muted)">A wrong turn isn't failure—it's data. Look at the grid. Which instruction first moves the robot into a wall?</p><p style="font-size:11px;color:var(--gold)">Challenge: find the energy at (3,3) before reaching the goal at (6,0).</p></div></aside></div>`}
function logicReset(doRender=true){logicRunId++;logicRunning=false;logicState={x:0,y:6,energy:false,step:0,status:'READY'};if(doRender&&route==='logic')render()}
function logicStep(){if(logicState.step>=logicCommands.length){logicState.status=logicCommands.length?'PROGRAM FINISHED':'ADD INSTRUCTIONS';return false}const cmd=logicCommands[logicState.step],d=LOGIC_DIRS[cmd];if(!d)return false;const x=logicState.x+d[0],y=logicState.y+d[1];logicState.step++;if(x<0||y<0||x>=7||y>=7||LOGIC_WALLS.has(x+','+y)){logicState.status='BLOCKED / DEBUG YOUR CODE';return false}logicState.x=x;logicState.y=y;if(x===3&&y===3)logicState.energy=true;if(x===6&&y===0){logicState.status=logicState.energy?'SOLVED!':'GOAL REACHED / ENERGY MISSING';if(logicState.energy){store(profileKey('logic-completed'),true);notify('CIRCUIT GARDEN SOLVED! Awesome debugging!')}return false}logicState.status='STEP '+logicState.step+' / '+logicCommands.length;return true}
function logicAdd(cmd){if(!LOGIC_DIRS[cmd]||logicRunning)return;if(logicCommands.length>=32){notify('Program limit: 32 commands. Try a shorter route.');return}logicCommands.push(cmd);store(profileKey('logic-program'),logicCommands);logicReset();}
function logicRun(){if(logicRunning)return;logicReset(false);if(!logicCommands.length){notify('Add some instructions first.');return}logicRunning=true;const runId=++logicRunId;render();const handle=setInterval(()=>{if(runId!==logicRunId||route!=='logic'){clearInterval(handle);return}const more=logicStep();if(!more){clearInterval(handle);logicRunning=false}render()},225)}

// ===== PHYSICS LAB / original transparent, real calculators =====
function calcLab(){return labType==='circuit'?WonderForgeLabs.led(labState.voltage,labState.resistance,labState.forwardVoltage):WonderForgeLabs.beam(labState.force,labState.span,labState.width,labState.height,labState.material)}
function fmtLab(n,digits=2){return Number.isFinite(n)?Number(n).toLocaleString('en-US',{maximumFractionDigits:digits}):'—'}
function labCircuitSvg(c){const a=c.severity==='unsafe'?'#ff988b':c.severity==='lit'?'#81e3d4':'#617d90';return `<svg role="img" aria-label="Series circuit schematic with a battery, resistor and LED" viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg"><defs><filter id="glow"><feGaussianBlur stdDeviation="8"/></filter></defs><path d="M160 90H365 M470 90H625V230H160V90" fill="none" stroke="#78b1c1" stroke-width="8" stroke-linecap="round"/><path d="M160 173h-22m22 18h-22M145 156v40M129 173v18" stroke="#f0c989" stroke-width="6"/><path d="M363 90l18 -21 19 42 19 -42 20 42 18 -21" stroke="#ffdb9b" stroke-width="6" fill="none"/><path d="M492 75v31m0-31 23 15-23 15m23-37v44" stroke="${a}" stroke-width="5" fill="none"/><circle cx="502" cy="90" r="43" fill="${a}" opacity="${c.severity==='dim'?.06:.21}"/><text x="90" y="144" fill="#eaf4f5" font-size="19">${fmtLab(c.voltage,1)} V</text><text x="357" y="50" fill="#ffe0a4" font-size="20">${fmtLab(c.resistance,0)} Ω</text><text x="482" y="155" fill="${a}" font-size="20">LED</text><text x="287" y="262" fill="#d9ebec" font-size="21">I = ${fmtLab(c.ma)} mA</text></svg>`}
function labBridgeSvg(c){const dip=Math.min(38,Math.max(0,c.deflectionMm*.6)),curve=(165+dip).toFixed(1);return `<svg role="img" aria-label="Simply supported bridge beam with central load and scaled visual bend" viewBox="0 0 760 300" xmlns="http://www.w3.org/2000/svg"><path d="M120 175Q380 ${curve} 640 175" stroke="#ffdd9a" stroke-width="22" fill="none" stroke-linecap="round"/><path d="M104 191l-28 48h56zM640 191l-28 48h56z" fill="#79c5c4"/><path d="M380 64v79" stroke="#ff988b" stroke-width="6"/><path d="m363 126 17 20 17-20" stroke="#ff988b" fill="none" stroke-width="6"/><text x="403" y="96" fill="#f9ccd1" font-size="19">${fmtLab(c.forceN,0)} N</text><path d="M120 250H640" stroke="#97b6bd" stroke-width="2" stroke-dasharray="8 9"/><text x="306" y="277" fill="#d3e6e8" font-size="19">${fmtLab(c.spanM,2)} m span</text><text x="136" y="76" fill="#81e3d4" font-size="18">Exaggerated deformation</text></svg>`}
function labResults(){const c=calcLab();if(labType==='circuit'){return `<div class="lab-visual">${labCircuitSvg(c)}</div><div class="lab-stat-grid"><div><b>${fmtLab(c.ma)} <small>mA</small></b><span>SIMULATED CURRENT</span></div><div><b>${fmtLab(c.powerW*1000)} <small>mW</small></b><span>RESISTOR POWER</span></div><div><b>${c.severity==='unsafe'?'STOP':c.severity==='lit'?'ON':'DIM'}</b><span>LED STATE (MODEL)</span></div></div><div class="lab-warning ${c.severity==='unsafe'?'lab-danger':''}">${esc(c.safety)} This is a calculator, not instructions to connect anything to Pi GPIO.</div>`}return `<div class="lab-visual">${labBridgeSvg(c)}</div><div class="lab-stat-grid"><div><b>${fmtLab(c.deflectionMm,3)} <small>mm</small></b><span>IDEAL MIDPOINT DEFLECTION</span></div><div><b>${fmtLab(c.stressMPa,2)} <small>MPa</small></b><span>ESTIMATED BENDING STRESS</span></div><div><b>${fmtLab(c.modulusPa/1e9,1)} <small>GPa</small></b><span>IDEALIZED ELASTIC MODULUS</span></div></div><div class="lab-warning">${esc(c.warning)}</div>`}
function labControl(label,key,min,max,step,unit=''){const value=labState[key];return `<label class="lab-control"><span>${label} <b data-lab-value="${key}">${fmtLab(value,2)} ${unit}</b></span><input type="range" min="${min}" max="${max}" step="${step}" data-lab="${key}" value="${value}"></label>`}
function labsPage(){const circuit=labType==='circuit';return `${pagehead('THE MAKER SCIENCE DECK / LIVE SIMULATIONS','Test the laws.','Use a transparent mathematical model. Predict a result, change one variable, and explain what happened.',`<span class="tag tag-lime">◉ RUNS ENTIRELY OFFLINE</span>`)}<div class="lab-tabs"><button class="${circuit?'active':''}" data-action="lab-tab" data-tab="circuit">⚡ CIRCUIT LAB</button><button class="${!circuit?'active':''}" data-action="lab-tab" data-tab="bridge">⌂ BRIDGE LAB</button><button data-route="fieldguide">▣ FIELD GUIDE ↗</button></div><div class="lab-layout"><section class="surface lab-stage"><div class="workspace-header"><div><strong>✦ ${circuit?'LED & RESISTOR SANDBOX':'ELASTIC BEAM EXPERIMENT'}</strong><br><small>${circuit?'VOLTAGE • RESISTANCE • POWER':'SPAN • LOAD • MATERIAL • CROSS-SECTION'}</small></div><span class="tag tag-gold">IDEALIZED SCIENCE</span></div><div id="lab-results">${labResults()}</div><div class="lab-prompt"><strong>YOUR CHALLENGE</strong><p>${circuit?'Predict what happens to current if you double resistance while keeping the voltage constant. Can you make the LED model stay below 10 mA?':'Keep the load and span fixed. Double the beam height and observe the change in deflection. Why does the height matter so much more than the width?'}</p></div></section><aside class="surface lab-sidebar"><div class="eyebrow">01 / CHANGE ONE VARIABLE</div><h3>${circuit?'Build a virtual circuit.':'Design a virtual beam.'}</h3>${circuit?[labControl('SUPPLY VOLTAGE','voltage',2,12,.5,'V'),labControl('RESISTOR','resistance',100,2200,10,'Ω'),labControl('LED FORWARD VOLTAGE','forwardVoltage',1.5,3.5,.1,'V')].join(''):[labControl('CENTER LOAD','force',10,500,10,'N'),labControl('BEAM SPAN','span',.3,3,.1,'m'),labControl('BEAM WIDTH','width',10,100,2,'mm'),labControl('BEAM HEIGHT','height',10,100,2,'mm'),`<label class="lab-control">BEAM MATERIAL<select id="lab-material" data-lab="material"><option value="wood" ${labState.material==='wood'?'selected':''}>Example softwood (10 GPa)</option><option value="aluminum" ${labState.material==='aluminum'?'selected':''}>Aluminum (69 GPa)</option><option value="steel" ${labState.material==='steel'?'selected':''}>Steel (200 GPa)</option><option value="plastic" ${labState.material==='plastic'?'selected':''}>Generic plastic (2.5 GPa)</option></select></label>`].join('')}<div class="lab-sidebar-footer"><button class="btn btn-primary" data-action="lab-save">${icon('save')} RECORD RESULTS</button><button class="btn btn-outline" data-action="lab-journal">${icon('books')} ADD TO MAKER JOURNAL</button><button class="btn btn-outline" data-action="lab-reset">RESET MODEL</button></div><p class="microtext">Not a physical simulator and not a substitute for equipment ratings, structural analysis, or adult supervision.</p></aside></div>`}
function updateLabResults(){const target=$('#lab-results');if(target)target.innerHTML=labResults();$$('[data-lab-value]').forEach(el=>{const key=el.dataset.labValue;el.textContent=fmtLab(labState[key],2)+(key==='voltage'||key==='forwardVoltage'?' V':key==='resistance'?' Ω':key==='force'?' N':key==='span'?' m':' mm')})}
function labReset(){labState={voltage:5,resistance:330,forwardVoltage:2,force:100,span:1,width:30,height:40,material:'wood'};render();store(profileKey('labs'),labState)}
function labSave(){const c=calcLab(),detail=labType==='circuit'?`Circuit model: ${c.voltage}V, ${c.resistance}ohm, diode ~${c.forwardVoltage}V; current ${fmtLab(c.ma,3)}mA, resistor ${fmtLab(c.powerW*1000,3)}mW.`:`Ideal beam: ${c.forceN}N, ${c.spanM}m span, ${c.widthMm}x${c.heightMm}mm, ${c.material}; deflection ${fmtLab(c.deflectionMm,3)}mm, stress ${fmtLab(c.stressMPa,2)}MPa.`;newProjectModal(null,labType==='circuit'?'LED current experiment':'Bridge deflection experiment');$('#project-notes').value=detail+'\nPrediction:\nObserved change:\nNext test:\n';}
// ===== ORIGINAL OFFLINE FIELD GUIDE =====
function fieldGuidePage(){const regions=['All',...new Set(lessons.map(x=>x.region))],list=lessons.filter(x=>selectedGuide==='All'||x.region===selectedGuide);return `${pagehead('A FIELD GUIDE YOU CAN KEEP','Discover. Question. Test.','Eighteen completely offline original mini-lessons. Each has a concept, an activity, evidence to record, and a safety note.',`<span class="tag tag-lime">${lessons.length} OFFLINE LESSONS</span>`)}<div class="guide-toolbar"><input id="guide-search" type="search" placeholder="Search for circuits, bridges, sound, Python…" aria-label="Find offline lessons" autocomplete="off"><div class="guide-region-tags">${regions.map(x=>`<button class="${selectedGuide===x?'active':''}" data-guide-region="${esc(x)}">${esc(x)}</button>`).join('')}</div></div><div id="guide-grid" class="guide-grid">${list.map(x=>`<button class="surface guide-card" data-lesson="${esc(x.id)}" data-guide-haystack="${esc([x.title,x.region,...x.keywords].join(' ').toLowerCase())}"><span class="eyebrow">${esc(x.region)} / ${esc(x.difficulty)}</span><h3>${esc(x.title)}</h3><span>READ → EXPERIMENT → RECORD</span><b>OPEN LESSON ↗</b></button>`).join('')}</div><p class="microtext" style="margin-top:18px">Content is original educational material, not offline Wikipedia. No sites or books are silently scraped or redistributed.</p>`}
function openLesson(id){const x=lessons.find(l=>l.id===id);if(!x)return;showModal(`<div class="eyebrow">OFFLINE FIELD GUIDE / ${esc(x.region.toUpperCase())}</div><h2>${esc(x.title)}</h2><p class="guide-concept">${esc(x.concept)}</p><div class="guide-lesson-section"><strong>01 / TRY IT</strong><p>${esc(x.activity)}</p></div><div class="guide-lesson-section"><strong>02 / COLLECT EVIDENCE</strong><p>${esc(x.evidence)}</p></div><div class="guide-lesson-section caution"><strong>03 / SAFETY</strong><p>${esc(x.safety)}</p></div><p>${esc(x.followUp)}</p><div class="modal-actions"><button class="btn btn-primary" data-action="guide-note" data-lesson-id="${esc(x.id)}">${icon('plus')} START A RESEARCH NOTE</button><button class="btn btn-outline" data-action="close-modal">CLOSE</button></div>`)}
function questsPage(){const categories=['All',...new Set(getQuests().map(q=>q.category))];let active=getQuests().filter(q=>filter==='All'||q.category===filter);const progress=questProgress();return `${pagehead('THE QUEST ATLAS / LEARN BY DOING','Adventures with a purpose.','Choose a challenge. Make an artifact. Test your ideas in the real world.',`<span class="tag tag-lime">${Object.values(progress).filter(Boolean).length} / ${getQuests().length} COMPLETED</span>`)}<div class="filter-bar" role="group" aria-label="Filter quests">${categories.map(c=>`<button class="filter-btn ${c===filter?'active':''}" data-filter="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="quest-grid">${active.map(q=>`<button class="quest-card" data-quest="${esc(q.id)}"><div style="display:flex;justify-content:space-between;align-items:start"><span class="tag ${progress[q.id]?'tag-lime':''}">${progress[q.id]?'✓ COMPLETED':esc(q.level||'QUEST')}</span><span class="tag">${esc(q.category)}</span></div><div class="emblem">${esc(q.emoji||'✦')}</div><h3>${esc(q.title)}</h3><p>${esc(q.description)}</p><div class="quest-card-bottom"><span>${esc(q.duration||'At your pace')}</span><strong>${progress[q.id]?'REVISIT ↗':'OPEN QUEST ↗'}</strong></div></button>`).join('')}</div>`}
function studiosPage(){return `${pagehead('THE CREATION DECK / REAL TOOLS','Make it in the real world.','A hand-picked directory of programs and creative workflows for the Pi 4B.',`<span class="tag tag-gold">INSTALLS NOT VERIFIED IN THIS PROTOTYPE</span>`)}<div class="studio-grid">${apps.map(a=>`<button class="studio-card" data-studio="${esc(a.id)}"><span class="studio-emoji" aria-hidden="true">${esc(a.emoji||'✦')}</span><h3>${esc(a.title)}</h3><p>${esc(a.description)}</p><div class="studio-programs">${esc(a.programs?.slice(0,3).join('   ·   ')||'Tools available separately')}</div><span class="launch-line">EXPLORE STUDIO ${icon('arrow')}</span></button>`).join('')}</div><p class="disclosure">This is an app directory, not a working desktop launcher. Tools listed may require separate installation, downloads, licensing review, physical hardware, or an adult's approval. The prototype never executes operating-system commands.</p>`}
function orbitPage(){
 const active=!!localAIStatus?.available;
 const status=active?`<span class="tag tag-lime">LOCAL AI • ${esc(localAIStatus.model)}</span>`:
   `<span class="tag tag-gold">SCRIPTED FALLBACK${localAIStatus?.reason?' • '+esc(localAIStatus.reason):''}</span>`;
 const proposal=pendingAIProposal?.preview;
 const approval=proposal?`<div class="orbit-approval"><div class="eyebrow">✦ SUGGESTED ACTION / NOT YET SAVED</div><h3>${esc(proposal.title)}</h3><p>${esc(proposal.question)}</p><p>Hypothesis: ${esc(proposal.hypothesis||'Write your own prediction.')}</p><div class="orbit-approval-actions"><button class="btn btn-primary" data-action="ai-approve">APPROVE & SAVE DRAFT ↗</button><button class="btn btn-outline" data-action="ai-dismiss">DISMISS</button></div><small>ORBIT cannot perform this action without your confirmation. No measurements or findings will be invented.</small></div>`:'';
 return `${pagehead('ORBIT / LOCAL INVENTION COMPANION','Questions become inventions.',active?'Real local small-model inference, two read-only tool calls maximum, and human-approved journal drafts.':'The offline guide is available. Add an adult-installed local model to unlock bounded agentic help.',status)}<div class="orbit-layout"><article class="surface conversation"><div class="conversation-head"><div class="orbit-head-icon">✳</div><div><h2>ORBIT <span style="color:var(--aqua)">/</span> WORKSHOP GUIDE</h2><p>${active?'LOCAL MODEL • NO CLOUD • READ-ONLY TOOLS':'SCRIPTED OFFLINE BACKUP • NO MODEL IS CURRENTLY RUNNING'}</p></div></div><div class="conversation-messages" id="chat-messages" aria-live="polite">${chatHistory.map(m=>`<div class="bubble ${m.speaker==='user'?'user':'agent'}"><small>${m.speaker==='user'?esc(P[profile].name.toUpperCase()):'✳ ORBIT'}</small>${esc(m.message)}</div>`).join('')}${orbitRequestPending?'<div class="bubble agent"><small>✳ ORBIT</small>Working locally… a Pi 4B may take a while.</div>':''}</div>${approval}<form class="chat-composer" id="chat-form"><label class="visually-hidden" for="chat-input">Ask ORBIT</label><input id="chat-input" maxlength="700" placeholder="Ask a question or plan a small experiment…" autocomplete="off" ${orbitRequestPending?'disabled':''}><button class="btn btn-primary" type="submit" ${orbitRequestPending?'disabled':''}>${orbitRequestPending?'THINKING…':'SEND '+icon('arrow')}</button></form></article><aside class="surface orbit-info"><div class="eyebrow">LOCAL INVENTION COMPANION</div>${orbitSculpture()}<h3>Stay curious.</h3><p>${active?'Your local model can search approved lessons and quests or run two idealized physics calculations. It cannot browse, open files, launch programs or execute code.':'Offline guidance works now. The optional Ollama service must be installed and the small model downloaded by an adult.'}</p><button class="btn btn-outline" data-action="ai-refresh">CHECK LOCAL MODEL ↻</button><div class="eyebrow">SOME THINGS TO ASK</div><div class="quick-prompts">${['Help me build a stronger bridge.','Find a science lesson on resistors.','Plan an experiment for my journal.','How do I start coding?','What can you actually do?'].map(s=>`<button data-prompt="${esc(s)}">✦ &nbsp; ${esc(s)} ↗</button>`).join('')}</div><p class="orbit-disclosure">${active?'Small language models can be wrong. All tools are local and read-only; journal drafts need your approval.':'No model inference is running. Ask a question for curated, scripted help.'} Never enter passwords, addresses or private information.</p></aside></div>`
}
function vaultPage(){let list=allProjects();return `${pagehead('PROJECT VAULT / YOUR INVENTION RECORD','The work worth keeping.','Record ideas, experiments, designs and lessons learned. All stored in this browser.',`<button class="btn btn-outline" data-action="vault-export">${icon('download')} EXPORT NOTES</button><label class="btn btn-outline" style="cursor:pointer">IMPORT JSON<input id="vault-import" type="file" accept="application/json,.json" hidden></label><button class="btn btn-primary" data-action="new-project">${icon('plus')} NEW PROJECT</button>`)}<div class="vault-head"><div class="eyebrow">${esc(P[profile].name.toUpperCase())} / ${list.length} SAVED CREATIONS</div><span class="tag tag-lime">◉ LOCAL BROWSER STORAGE</span></div><div class="vault-grid">${list.length?list.map(p=>`<button class="vault-card" data-project="${esc(p.id)}"><span class="emoji">${esc(p.icon||'📐')}</span><span class="tag ${p.sample?'tag-gold':'tag-lime'}" style="align-self:start;margin-top:14px">${p.sample?'SAMPLE PROJECT':'MY INVENTION'}</span><h3>${esc(p.title)}</h3><p>${esc(p.notes||'An idea waiting to become real.')}</p><small>UPDATED ${esc(new Date(p.updated).toLocaleDateString('en-US'))} <span style="float:right;color:var(--aqua)">OPEN ↗</span></small></button>`).join(''):`<div class="surface empty-state"><div class="giant">✦</div><h3>Great things start as small ideas.</h3><p>Create a project notebook to keep sketches, tests, and the fascinating things that didn't work the first time.</p><button class="btn btn-primary" data-action="new-project">${icon('plus')} START MY FIRST PROJECT</button></div>`}</div><p class="disclosure">Browser-local storage is not a secure account system or a permanent backup. Export notebooks regularly. ${systemSession?.linux_identity_enforced?'Your current browser is separated by this Linux account; your shared Team Forge copies live in a group-owned directory.':'Switching browser profiles separates keys only within this application; other local computer users may access browser data.'}</p>`}
function teamPage(){return `${pagehead('TEAM FORGE / THE BROTHERHOOD WORKSHOP','Two minds. One masterpiece.','Build side-by-side, take turns, or collaborate on one original invention.',`<button class="btn btn-primary" data-action="enter-team">ENTER SHARED WORKSHOP ${icon('arrow')}</button>`)}<div class="surface team-feature"><div class="eyebrow">✦ THE COOPERATIVE CHALLENGE</div><h2>THE PROJECT IS BIGGER<br>THAN EITHER OF YOU.</h2><p>Invent a skybridge rescue station together. One designs the structure; the other makes it useful. Then swap.</p><button class="btn btn-primary" data-action="enter-team">BUILD AS TEAM FORGE ${icon('arrow')}</button></div><div class="section-titlebar"><div><div class="eyebrow">THREE RULES OF THE WORKSHOP</div><h2>Build as a team</h2></div></div><div class="team-grid"><article class="surface team-card"><div class="step-num">01</div><h3>Driver & Navigator.</h3><p>One controls the mouse or keyboard while the other explains, checks and makes suggestions. Both have an equal say.</p></article><article class="surface team-card"><div class="step-num">02</div><h3>Trade places.</h3><p>Use the optional five-minute timer to swap roles. The goal is two makers, not one player and one spectator.</p><div class="team-timer" id="team-timer">${fmtNum(Math.floor(demoTimer/60))}:${fmtNum(demoTimer%60)}</div><button class="btn btn-outline" data-action="team-timer">${icon('clock')} ${timerId?'PAUSE':'START'} ROLE TIMER</button></article><article class="surface team-card"><div class="step-num">03</div><h3>Share what changed.</h3><p>Show what worked, what failed, and how your combined design improved. The lesson is as important as the build.</p><button class="btn btn-outline" data-action="team-note">${icon('plus')} RECORD A TEAM IDEA</button></article></div>`}
const LIBRARY=[{icon:'🔭',title:'The Night Sky',desc:'Observing stars, seasons, planets and space science.',topic:'Look up the Moon phases using Stellarium or a paper log.'},{icon:'🌿',title:'Life on Earth',desc:'Biology, ecosystems, field studies and stewardship.',topic:'Compare plant growth in different light conditions.'},{icon:'⚙️',title:'How Things Work',desc:'Forces, simple machines, engineering and inventions.',topic:'Test which bridge structure carries more weight.'},{icon:'🧭',title:'History & Cultures',desc:'Civilizations, maps, inventions and primary sources.',topic:'Trace an invention from its first prototype.'},{icon:'📚',title:'Books & Research',desc:'Ideas for reading, evidence and better questions.',topic:'Find two sources that disagree about a claim.'},{icon:'🤝',title:'Character & Service',desc:'Learning to help, cooperate and consider others.',topic:'Design an invention that serves your neighbors.'}];
function libraryPage(){return `${pagehead('THE DISCOVERY LIBRARY / FOLLOW YOUR QUESTIONS','A universe of things to learn.','Research prompts and planned resources, designed for curiosity over endless scrolling.',`<span class="tag tag-gold">OFFLINE REFERENCE PACKS NOT BUNDLED</span>`)}<div class="library-grid">${LIBRARY.map((it,i)=>`<button class="surface library-card" data-topic="${i}" style="text-align:left"><span class="big-icon">${it.icon}</span><h3>${esc(it.title)}</h3><p>${esc(it.desc)}</p><span class="side-link">OPEN DISCOVERY NOTE ${icon('arrow')}</span></button>`).join('')}</div><p class="disclosure">For real offline books, simulations, and reference libraries, content must be downloaded and reviewed by an adult using tools such as Kiwix and Kolibri. Nothing here claims that copyright-protected or third-party materials are preinstalled.</p>`}
function parentPage(){return `${pagehead('PARENT DESK / FAMILY GUIDELINES','Guidance without a cage.','A shared creative station for real learning, thoughtful boundaries and meaningful collaboration.',`<button class="btn btn-outline" data-action="family-export">${icon('download')} EXPORT FAMILY SUMMARY</button>`)}<div class="family-note"><strong>PROTOTYPE SAFETY DISCLOSURE.</strong> This interface has no administrative enforcement. It cannot block websites, restrict Linux accounts, protect browser data from other local users, or guarantee supervision. Real parental controls require separate OS-level implementation and testing.</div><div class="family-grid"><article class="surface family-card"><span class="big-icon">🛡️</span><h3>Account separation</h3><p>Recommended: one standard Linux user each, plus a carefully permissioned shared-project directory. Do not rely on these browser workspace labels for privacy.</p><span class="tag tag-gold">NEEDS OS IMPLEMENTATION</span></article><article class="surface family-card"><span class="big-icon">🌱</span><h3>Learning that builds character</h3><p>Practice service, honesty, kindness and stewardship. Faith-oriented reflection can coexist with accurate scientific study and critical thinking.</p><span class="tag tag-lime">FAMILY-LED APPROACH</span></article><article class="surface family-card"><span class="big-icon">🤝</span><h3>Brotherhood sessions</h3><p>Alternate driver and navigator roles, keep projects cooperative, and let each brother teach the other something new every week.</p><span class="tag tag-lime">INCLUDED IN TEAM FORGE</span></article><article class="surface family-card"><span class="big-icon">📴</span><h3>Offline by default</h3><p>The browser demo works without outside services. Installing programs, downloading content or enabling a future cloud helper should be adult-controlled.</p></article><article class="surface family-card"><span class="big-icon">🧰</span><h3>Safe maker experiments</h3><p>Adult supervision for electronics, power supplies, soldering, physical tools, or potentially risky science activities. Favor low-voltage projects.</p></article><article class="surface family-card"><span class="big-icon">✨</span><h3>Curiosity over scores</h3><p>No streak anxiety, rankings, purchases, social feed, persuasive notifications or endless engagement loops. Celebrate patient experimentation.</p></article></div>`}
function settingsPage(){return `${pagehead('SYSTEMS / SETTINGS','Make it yours.','A low-resource, personal environment. Changes stay on this device.',`<span class="tag tag-lime">◉ RASPBERRY PI 4B · 4 GB TARGET</span>`)}<div class="settings-grid"><article class="surface settings-card"><div class="eyebrow">COLOR ATMOSPHERE</div><h3>Choose the mood.</h3><p>A different atmosphere for the same maker universe.</p><label for="theme-choice" style="display:block">THEME</label><select id="theme-choice"><option value="starlight" ${appPrefs.theme==='starlight'?'selected':''}>Starlight / Alpine blue</option><option value="dawn" ${appPrefs.theme==='dawn'?'selected':''}>Dawn / Copper violet</option><option value="contrast" ${appPrefs.theme==='contrast'?'selected':''}>High Contrast / Clear night</option></select></article><article class="surface settings-card"><div class="eyebrow">MOTION & COMFORT</div><h3>Built to be gentle.</h3><p>Keep the desktop readable and light on the Pi 4B.</p><label><input id="reduce-motion" type="checkbox" ${appPrefs.reducedMotion?'checked':''}> Reduce visual motion</label><label><input type="checkbox" checked disabled> No external tracking in this prototype</label></article><article class="surface settings-card"><div class="eyebrow">THE HARDWARE REALITY</div><h3>One Pi. Plenty of potential.</h3><p>Target: Raspberry Pi 4B, ARM64 OS, 4 GB RAM. No heavy real-time GPU animation or background large-language model required.</p><span class="tag tag-gold">NOT LIVE HARDWARE MONITORING</span></article><article class="surface settings-card"><div class="eyebrow">YOUR WORKSPACE</div><h3>${esc(P[profile].name)}</h3><p>Switch the browser workspace or export projects before clearing your browser.</p><button class="btn btn-outline" data-action="switch-profile">SWITCH WORKSHOP ${icon('arrow')}</button></article><article class="surface settings-card"><div class="eyebrow">ABOUT THIS PROTOTYPE</div><h3>WonderForge Reforged</h3><p>Build 0.5 — local desktop and teaching environment with new physics labs and offline field guide. This is a local browser app, not a replacement OS, a virtual machine, or a locked-down kiosk.</p><button class="btn btn-outline" data-action="about">WHAT IS REAL? ${icon('eye')}</button></article><article class="surface settings-card"><div class="eyebrow">LOCAL DATA TOOLS</div><h3>Keep an escape hatch.</h3><p>Save copies of projects and blueprints. Installed Linux sessions sync work to private SQLite; export backups as well.</p><button class="btn btn-outline" data-route="vault">OPEN MY PROJECTS ${icon('folder')}</button></article></div>`}
// Popup content is assembled from trusted templates and escaped user data only.
function showModal(inner){$('#modal').innerHTML=`<div class="modal-card" role="dialog" aria-modal="true" aria-label="WonderForge dialog"><button class="modal-x" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button>${inner}</div>`;$('#modal').hidden=false;$('#modal').querySelector('button,input,textarea')?.focus()}
function closeModal(){$('#modal').hidden=true;$('#modal').innerHTML=''}
function questModal(id){const q=findQuest(id);if(!q){notify('Quest details are unavailable.');return}const done=!!questProgress()[id];showModal(`<div class="eyebrow">QUEST ATLAS / ${esc(q.category)} · ${esc(q.level||'EXPLORER')}</div><h2>${esc(q.emoji||'✦')} ${esc(q.title)}</h2><p>${esc(q.description)}</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin:15px 0"><span class="tag">${esc(q.duration||'Self-paced')}</span><span class="tag tag-gold">${esc(q.artifact||'Creative result')}</span></div><div class="eyebrow">THE MISSION / STEP BY STEP</div><ol class="quest-steps">${(q.steps||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="eyebrow">CO-OP TACTIC</div><p>${esc(q.brothers||'Work together and swap roles.')}</p><div class="eyebrow">STRETCH YOUR THINKING</div><p>${esc(q.stretch||'Find a way to test a better version.')}</p><div class="modal-actions"><button class="btn btn-primary" data-action="quest-toggle" data-id="${esc(q.id)}">${icon('check')} ${done?'MARK IN PROGRESS':'MARK QUEST COMPLETE'}</button><button class="btn btn-outline" data-action="quest-hint" data-id="${esc(q.id)}">${icon('spark')} SHOW A HINT</button><button class="btn btn-outline" data-route="builder">${icon('box')} OPEN BUILDER</button><button class="btn btn-outline" data-action="journal-quest" data-id="${esc(q.id)}">${icon('books')} RECORD EXPERIMENT</button></div><div id="hint-output" style="font-size:12px;color:var(--gold);margin:6px 0"></div>`)}
function studioModal(id){const a=apps.find(p=>p.id===id);if(!a)return;showModal(`<div class="eyebrow">CREATION STUDIOS / PROGRAM DIRECTORY</div><h2>${esc(a.emoji||'✦')} ${esc(a.title)}</h2><p>${esc(a.description)}</p><div class="eyebrow" style="margin-top:24px">PROGRAMS TO EXPLORE</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin:13px 0">${(a.programs||[]).map(p=>`<span class="tag">${esc(p)}</span>`).join('')}</div><div class="eyebrow" style="margin-top:22px">YOUR FIRST PROJECT</div><p>${esc(a.firstProject||'Invent something new.')}</p><div class="family-note"><strong>COMPATIBILITY NOTE:</strong> ${esc(a.availability||'Availability depends on the device and installation.')}</div><div class="modal-actions"><button class="btn btn-primary" data-action="new-project" data-prefill="${esc('My '+a.title+' experiment')}">${icon('plus')} CREATE A PROJECT NOTE</button>${a.id==='code-engine'?`<button class="btn btn-outline" data-route="logic">${icon('command')} TRY ROBOT LOGIC LAB</button>`:''}${(APP_STUDIOS[a.id]||[]).filter(id=>installedApps.some(ap=>ap.id===id&&ap.installed)).map(id=>`<button class="btn btn-outline" data-action="launch-app" data-app-id="${esc(id)}">LAUNCH ${esc(installedApps.find(ap=>ap.id===id).name)} ↗</button>`).join('')}</div>`)}
function newProjectModal(id=null,prefill=''){const item=allProjects().find(p=>p.id===id);showModal(`<div class="eyebrow">PROJECT VAULT / ${item?'EDIT':'CREATE'} RECORD</div><h2>${item?'Your invention notebook.':'Give your idea a name.'}</h2><p>What are you making? What did you try? What did you learn? The best inventions have excellent notes.</p><form id="project-form"><div class="field"><label for="project-title">PROJECT TITLE</label><input id="project-title" maxlength="100" required placeholder="e.g. The impossible floating bridge" value="${esc(item?.title||prefill)}"></div><div class="field"><label for="project-notes">IDEAS, SKETCH NOTES, TESTS & RESULTS</label><textarea id="project-notes" maxlength="5000" placeholder="My hypothesis is… The first test showed… Next time I'll…">${esc(item?.notes||'')}</textarea></div><div class="modal-actions"><button class="btn btn-primary" type="submit">${icon('save')} SAVE PROJECT</button>${item?`<button class="btn btn-outline" type="button" data-action="delete-project" data-id="${esc(id)}">DELETE NOTEBOOK</button>`:''}</div></form>`);$('#project-form').dataset.id=id||'';$('#project-title').focus()}
function saveProject(form){const id=form.dataset.id;const title=$('#project-title').value.trim();const notes=$('#project-notes').value.trim();if(!title)return;const list=allProjects();const previous=list.find(x=>x.id===id);const item={id:previous?.id||'wf-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),title:title.slice(0,100),notes:notes.slice(0,5000),icon:'📐',updated:new Date().toISOString(),sample:false};if(previous){list.splice(list.indexOf(previous),1,item)}else list.unshift(item);if(setProjects(list)){closeModal();render();notify('Project saved locally. Consider exporting a backup.')}else notify('Browser storage is unavailable; project not saved.')}
function openProjectDelete(id){if(!confirm('Delete this project notebook from this browser?'))return;setProjects(allProjects().filter(p=>p.id!==id));closeModal();render();notify('Project removed.')}
function downloadJSON(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function summarizeFamily(){return Object.fromEntries(Object.keys(P).map(id=>{let completed=read(profileKey('quests',id),{});return[id,{workspace:P[id].name,completed:Object.keys(completed).filter(k=>completed[k]),projectCount:allProjects(id).length}] }));}
function askOrbit(input){const t=input.toLowerCase();let response='That is a promising question. Let’s make it testable. First, describe what success would look like. Then change only one part of your design, compare two versions, and record what happened. What could you try in the next ten minutes?';if(/bridge|tower|fortress|strong|build|structure/.test(t))response='Engineering challenge! ① Build a simple span or tower. ② Make a second version with triangular braces. ③ Test both with the same load. ④ Record where they bend or fail. Which variable did you change, and what did you discover?';else if(/robot|led|sensor|circuit|pico|electronic/.test(t))response='Let’s give your robot a purpose! Start with the chain INPUT → DECISION → OUTPUT. A sensor could be the input, a simple Python condition the decision, and an LED the output. Try your idea in a safe low-voltage circuit with an adult. Which input do you want it to notice?';else if(/mars|space|planet|moon|astron/.test(t))response='Great cosmic question! Begin with one real constraint: temperature, breathable air, radiation, water or energy. Sketch your habitat, label the systems, and compare each requirement with a science reference. Which single system will you design first?';else if(/python|scratch|code|program|game/.test(t))response='Let’s code one tiny behavior, not an entire game. ① Pick one thing that moves. ② Define an input. ③ Write the simplest rule. ④ Test it, then change one value. When it works, add sound or a challenge. What should happen when you press a key?';else if(/art|draw|music|sound|paint|animate/.test(t))response='Art is engineering for the imagination. Pick one mood, three colors, and one repeated shape or sound. Make a quick draft, then ask your brother what emotion it communicates. What is the one feeling your creation should evoke?';else if(/experiment|science|hypothesis|test/.test(t))response='A great experiment starts with a specific question. Say “If I change X, what happens to Y?” Keep everything else the same. Try three measurements and write down the result, including surprises. What is your independent variable?';else if(/\b(?:what can|are you real|ai|model|actually)\b/.test(t))response='I am a scripted, offline prototype—not a trained AI model. I recognize a few topic words and offer prepared ideas for engineering, coding, science and art. I cannot browse, run commands, reason over files or control your Pi. An optional local model is available through the adult-approved Ollama setup. It can use only bounded read-only tools, with approval for Maker Journal drafts.';else if(/hello|hi|hey/.test(t))response=`Hello, ${P[profile].name}! Every excellent invention begins with curiosity. Would you rather build a world, solve a physical problem, learn code, or design a game today?`;
// Local original Field Guide retrieval. Scored keyword/title matching, NOT an LLM.
if(!/\b(?:what can|are you real|ai|model|actually|hello|hi|hey)\b/.test(t)){
 const words=t.match(/[a-z]{3,}/g)||[];
 const ignored=new Set(['the','and','how','what','can','could','with','from','does','make','have','this','that','would','should','help','about','work','want','need','please','test','using','tell','explain','trying']);
 const search=words.filter(x=>!ignored.has(x));
 const ranked=lessons.map(l=>{
  const title=l.title.toLowerCase();
  const keywords=l.keywords||[];
  const score=search.reduce((sum,word)=>sum+(keywords.includes(word)?4:0)+(title.includes(word)?3:0)+(l.concept.toLowerCase().includes(word)?1:0),0);
  return {lesson:l,score};
 }).sort((a,b)=>b.score-a.score);
 if(ranked[0]?.score>=5){const l=ranked[0].lesson;response=l.concept+' TRY THIS: '+l.activity+' RECORD: '+l.evidence+' SAFETY: '+l.safety+' Source: original WonderForge Offline Field Guide / '+l.title+'. Open Offline Field Guide for the complete lesson.'}
}
chatHistory.push({speaker:'user',message:input.slice(0,350)},{speaker:'agent',message:response});chatHistory=chatHistory.slice(-30);store(profileKey('chat'),chatHistory);if(route==='orbit')render();}
// Isometric 12x12 builder — drawn only on state changes, no continuous GPU loop.
const CELL_W=51,CELL_H=25,BLOCK_H=22,SIZE=12,CX=550,CY=235;
function rotateXY(x,y){if(angle===0)return[x,y];if(angle===1)return[SIZE-1-y,x];if(angle===2)return[SIZE-1-x,SIZE-1-y];return[y,SIZE-1-x]}
function unrotateXY(x,y){if(angle===0)return[x,y];if(angle===1)return[y,SIZE-1-x];if(angle===2)return[SIZE-1-x,SIZE-1-y];return[SIZE-1-y,x]}
function shade(hex,k){const n=parseInt(hex.slice(1),16);return '#'+[n>>16,n>>8&255,n&255].map(v=>Math.min(255,Math.max(0,Math.round(v*k))).toString(16).padStart(2,'0')).join('')}
function poly(ctx,pts,fill,stroke){ctx.beginPath();ctx.moveTo(...pts[0]);pts.slice(1).forEach(a=>ctx.lineTo(...a));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function iso(x,y,z){return [CX+(x-y)*CELL_W/2,CY+(x+y)*CELL_H/2-z*BLOCK_H]}
function renderCanvas(){const canvas=$('#build-canvas');if(!canvas)return;const ctx=canvas.getContext('2d');const W=canvas.width,H=canvas.height;ctx.clearRect(0,0,W,H);const shine=ctx.createRadialGradient(CX,440,50,CX,440,430);shine.addColorStop(0,'#37777a33');shine.addColorStop(1,'#37777a00');ctx.fillStyle=shine;ctx.fillRect(0,0,W,H);ctx.fillStyle='#5c94a520';ctx.beginPath();ctx.ellipse(CX,465,370,140,0,0,Math.PI*2);ctx.fill();for(let x=0;x<SIZE;x++)for(let y=0;y<SIZE;y++){const [ix,iy]=iso(x,y,0);poly(ctx,[[ix,iy],[ix+CELL_W/2,iy+CELL_H/2],[ix,iy+CELL_H],[ix-CELL_W/2,iy+CELL_H/2]],(x+y)%2?'#4b829722':'#6396a32c',gridVisible?'#8ab9c43f':null)}const items=Object.entries(blocks).filter(([k,v])=>/^\d+,\d+,\d+$/.test(k)&&MATERIALS.some(m=>m.id===v)).map(([k,v])=>{const [x,y,z]=k.split(',').map(Number);if(x>=SIZE||y>=SIZE||z>7)return null;const [rx,ry]=rotateXY(x,y);return{x,y,z,rx,ry,color:MATERIALS.find(m=>m.id===v).hex}}).filter(Boolean).sort((a,b)=>(a.rx+a.ry+b.z*.001)-(b.rx+b.ry+a.z*.001)||a.z-b.z);for(const c of items){const [sx,sy]=iso(c.rx,c.ry,c.z);const T=[[sx,sy],[sx+CELL_W/2,sy+CELL_H/2],[sx,sy+CELL_H],[sx-CELL_W/2,sy+CELL_H/2]],R=[[sx+CELL_W/2,sy+CELL_H/2],[sx,sy+CELL_H],[sx,sy+CELL_H+BLOCK_H],[sx+CELL_W/2,sy+CELL_H/2+BLOCK_H]],L=[[sx-CELL_W/2,sy+CELL_H/2],[sx,sy+CELL_H],[sx,sy+CELL_H+BLOCK_H],[sx-CELL_W/2,sy+CELL_H/2+BLOCK_H]];poly(ctx,L,shade(c.color,.62),'#06182580');poly(ctx,R,shade(c.color,.79),'#06182580');poly(ctx,T,shade(c.color,1.18),'#e3ffff33')}
const [ox,oy]=iso(0,0,layer);ctx.font='bold 13px system-ui';ctx.textAlign='left';ctx.fillStyle='#9ee7d8';ctx.fillText('Z '+fmtNum(layer),20,52);ctx.fillStyle='#b6cbd6';ctx.fillText('12 × 12 / VOXEL FIELD',20,72);
}
function setupCanvas(){requestAnimationFrame(renderCanvas);const canvas=$('#build-canvas');if(!canvas)return;canvas.addEventListener('click',ev=>{const rect=canvas.getBoundingClientRect();const px=(ev.clientX-rect.left)/rect.width*canvas.width,py=(ev.clientY-rect.top)/rect.height*canvas.height;const u=(px-CX)/(CELL_W/2),v=(py-CY-CELL_H/2+layer*BLOCK_H)/(CELL_H/2),rx=Math.floor((u+v)/2+.5),ry=Math.floor((v-u)/2+.5);if(rx<0||ry<0||rx>=SIZE||ry>=SIZE){notify('Try clicking the grid within the blueprint boundary.');return}const [x,y]=unrotateXY(rx,ry),key=x+','+y+','+layer;pushUndo();if(erase)delete blocks[key];else blocks[key]=material;saveBlocks();});}
function pushUndo(){undoStack.push({...blocks});if(undoStack.length>50)undoStack.shift();redoStack=[]}
function saveBlocks(){store(profileKey('blocks'),blocks);renderCanvas();const cnt=$('#builder-count');if(cnt)cnt.textContent=Object.keys(blocks).length;}
function makeExample(){pushUndo();blocks={};for(let x=3;x<=8;x++)for(let y=3;y<=8;y++)blocks[x+','+y+',0']='grass';for(let z=1;z<=4;z++)for(const [x,y]of[[3,3],[8,3],[3,8],[8,8]])blocks[x+','+y+','+z]='stone';for(let x=4;x<=7;x++)for(let y=4;y<=7;y++)blocks[x+','+y+',4']='wood';for(let z=5;z<=6;z++)for(const [x,y]of[[4,4],[4,7],[7,4],[7,7]])blocks[x+','+y+','+z]='gold';saveBlocks();notify('Sky platform loaded. Rotate it, extend it or create your own.');render();}
async function importBlueprint(file){if(!file)return;try{if(file.size>1500000)throw Error('File must be below 1.5 MB');const data=JSON.parse(await file.text());if(data.format!=='wonderforge-blueprint'||(data.version!==1&&data.version!==3)||!data.blocks||typeof data.blocks!=='object'||Array.isArray(data.blocks))throw Error('Unrecognized blueprint format');let clean={};for(const [k,v]of Object.entries(data.blocks)){const m=k.match(/^(\d+),(\d+),(\d+)$/);if(m&&+m[1]<SIZE&&+m[2]<SIZE&&+m[3]<8&&MATERIALS.some(x=>x.id===v))clean[k]=v}pushUndo();blocks=clean;saveBlocks();render();notify('Imported '+Object.keys(clean).length+' blocks.')}catch(err){notify('Blueprint import failed: '+err.message)}}
async function importVault(file){if(!file)return;try{if(file.size>3000000)throw Error('File must be below 3 MB');const d=JSON.parse(await file.text());if(d.format!=='wonderforge-vault'||!Array.isArray(d.projects))throw Error('Unsupported vault backup');const clean=d.projects.slice(0,100).filter(x=>x&&typeof x.title==='string').map(x=>({id:String(x.id||'import-'+Math.random().toString(36).slice(2)).slice(0,80),title:x.title.slice(0,100),notes:String(x.notes||'').slice(0,5000),updated:new Date().toISOString(),icon:'📐',sample:false}));if(!confirm('Import '+clean.length+' projects into '+P[profile].name+'? This will replace the current vault for this browser profile.'))return;setProjects(clean);render();notify('Imported '+clean.length+' project records.')}catch(err){notify('Import failed: '+err.message)}}
// Maker Journal ties a quest to an actual experiment and a record of evidence.
const journalEntries=()=>WonderForgeJournal.sanitize(read(profileKey('journal'),[]));
function journalPage(){
 const entries=journalEntries(),stats=WonderForgeJournal.summarize(entries,getQuests());
 const edited=entries.find(e=>e.id===journalEditId)||{};
 const currentQuest=edited.questId||journalQuestPrefill||'';
 const field=(id,label,hint,rows=3)=>`<label class="journal-field" for="journal-${id}"><b>${label}</b><small>${hint}</small><textarea id="journal-${id}" name="${id}" maxlength="2400" rows="${rows}">${esc(edited[id]||'')}</textarea></label>`;
 return `${pagehead('THE MAKER JOURNAL / EVIDENCE OVER POINTS','Proof of curiosity.','Write a hypothesis, explain your method, record observations and reason about the result.',`<button class="btn btn-outline" data-action="journal-export">${icon('download')} EXPORT JOURNAL</button><label class="btn btn-outline" style="cursor:pointer">IMPORT BACKUP<input id="journal-import" type="file" accept=".json,application/json" hidden></label>`)}
 <div class="journal-summary"><div><strong>${stats.entries}</strong><span>EXPERIMENTS SAVED</span></div><div><strong>${stats.evidenced}</strong><span>WITH COMPLETE EVIDENCE</span></div><div><strong>${stats.linkedQuests}</strong><span>QUESTS WITH EVIDENCE</span></div></div>
 <div class="journal-layout"><section class="surface journal-editor"><div class="eyebrow">${journalEditId?'EDIT RECORD':'CREATE RECORD'} / ACTUAL EXPERIMENT</div><h2>${journalEditId?'Improve your observations':'What did you test?'}</h2><form id="journal-form" data-id="${esc(journalEditId||'')}"><label for="journal-title">EXPERIMENT TITLE</label><input name="title" id="journal-title" maxlength="100" required minlength="3" placeholder="e.g. Does a triangle brace strengthen my bridge?" value="${esc(edited.title||'')}">
 <label for="journal-quest">LINK TO QUEST (OPTIONAL)</label><select id="journal-quest" name="questId"><option value="">Independent investigation</option>${getQuests().map(q=>`<option value="${esc(q.id)}" ${q.id===currentQuest?'selected':''}>${esc(q.title)}</option>`).join('')}</select>
 ${field('question','QUESTION','What do you wonder about?',2)}${field('hypothesis','HYPOTHESIS','Predict what will happen and why.')}${field('method','METHOD / FAIR TEST','Change one variable and keep the others constant.')}${field('observation','OBSERVATIONS','Record numbers, measurements or descriptions.')}${field('conclusion','CONCLUSION','What does the evidence support?')}${field('nextStep','NEXT ITERATION','What would you try differently?',2)}
 <div class="journal-actions"><button class="btn btn-primary" type="submit">${icon('save')} SAVE EXPERIMENT</button><button class="btn btn-outline" type="button" data-action="journal-new">START BLANK</button></div></form><p class="disclosure">A complete record is evidence of documenting a test, not an automatic assessment of scientific accuracy. Physical experiments require appropriate adult supervision.</p></section>
 <aside class="journal-list"><div class="eyebrow">EXPERIMENT RECORDS / ${entries.length} OF 75</div>${entries.length?entries.map(e=>`<article class="surface journal-item"><span class="tag ${WonderForgeJournal.hasEvidence(e)?'tag-lime':'tag-gold'}">${WonderForgeJournal.hasEvidence(e)?'DOCUMENTED EVIDENCE':'DRAFT'}</span><h3>${esc(e.title)}</h3><p>${esc(e.question||e.hypothesis||'A question worth investigating.')}</p><div class="journal-actions"><button class="btn btn-outline" data-action="journal-edit" data-id="${esc(e.id)}">EDIT ↗</button><button class="btn btn-outline" data-action="journal-delete" data-id="${esc(e.id)}">DELETE</button></div></article>`).join(''):`<article class="surface empty-state"><h3>Your discoveries belong here.</h3><p>Write down a question and collect evidence before deciding what it means.</p></article>`}</aside></div>`;
}
function saveJournal(form){
 const entry={id:form.dataset.id||undefined};for(const key of ['title','questId','question','hypothesis','method','observation','conclusion','nextStep'])entry[key]=String(form.elements.namedItem(key)?.value||'');
 try{const valid=WonderForgeJournal.validate(entry);let all=journalEntries();const idx=all.findIndex(e=>e.id===valid.id);if(idx>=0)all[idx]=valid;else all.unshift(valid);if(all.length>WonderForgeJournal.maxEntries)throw Error('Archive older entries before adding more.');
 if(!store(profileKey('journal'),all))throw Error('Storage unavailable');journalEditId=valid.id;journalQuestPrefill='';render();notify(WonderForgeJournal.hasEvidence(valid)?'Experiment saved with documented evidence.':'Draft saved; add observations and a conclusion when ready.');
 }catch(e){notify('Could not save: '+e.message)}
}
function journalFromLab(){
 const c=calcLab();const isCircuit=labType==='circuit';const question=isCircuit?'How does resistance change LED current?':'How does beam height change deflection?';
 const obs=isCircuit?`Model: ${c.voltage} V supply; ${c.resistance} ohm resistor; ${c.forwardVoltage} V LED drop. Current ${fmtLab(c.ma,3)} mA and resistor ${fmtLab(c.powerW*1000,3)} mW.`:`Model: ${c.forceN} N, ${c.spanM} m span, ${c.widthMm} mm width, ${c.heightMm} mm height, ${c.material}. Deflection ${fmtLab(c.deflectionMm,3)} mm; stress ${fmtLab(c.stressMPa,3)} MPa.`;
 journalEditId=null;journalQuestPrefill='';go('journal');$('#journal-title').value=isCircuit?'LED resistor model investigation':'Beam deflection model investigation';$('#journal-question').value=question;$('#journal-method').value='Idealized software model only. Change one slider while holding all others constant; compare readings.';$('#journal-observation').value=obs+'\nNot measured on real hardware.';notify('Model data copied into a journal draft. Add a prediction and a conclusion.');
}
function journalDelete(id){if(!confirm('Delete this experiment record? This cannot be undone without a backup.'))return;store(profileKey('journal'),journalEntries().filter(e=>e.id!==id));if(journalEditId===id)journalEditId=null;render();notify('Experiment record deleted.')}
async function importJournal(file){if(!file)return;try{if(file.size>300000)throw Error('File exceeds 300 KB');const data=JSON.parse(await file.text()),all=WonderForgeJournal.parseImport(data);if(!confirm('Replace the current journal with '+all.length+' imported experiments?'))return;store(profileKey('journal'),all);journalEditId=null;render();notify('Imported '+all.length+' experiment records.')}catch(e){notify('Import failed: '+e.message)}}
