function drawSearch(){const query=($('#command-input').value||'').toLowerCase().trim();const items=NAV.filter(([id,title])=>!query||title.toLowerCase().includes(query));$('#command-results').innerHTML=items.map(([id,title,ic])=>`<button class="command-result" data-route="${id}">${icon(ic)} ${esc(title)}<small>↵</small></button>`).join('')||'<p style="padding:18px;color:#afc7d1">No matching destinations.</p>'}
// Event delegation survives page re-render. Trusted action names are from a fixed map.
document.addEventListener('click',e=>{const btn=e.target.closest('button,[data-action],[data-enter],[data-quest],[data-region],[data-studio],[data-topic],[data-material],[data-project],[data-filter],[data-prompt]');if(!btn)return;if(btn.dataset.sharedId){void openSharedItem(btn.dataset.sharedId);return}if(btn.dataset.enter){enter(btn.dataset.enter);return}if(btn.dataset.route){closeModal();closeSearch();go(btn.dataset.route);return}if(btn.dataset.region){selectedRegion=btn.dataset.region;render();return}if(btn.dataset.quest){questModal(btn.dataset.quest);return}if(btn.dataset.studio){studioModal(btn.dataset.studio);return}if(btn.dataset.project){newProjectModal(btn.dataset.project);return}if(btn.dataset.lesson){openLesson(btn.dataset.lesson);return}if(btn.dataset.guideRegion){selectedGuide=btn.dataset.guideRegion;render();return}if(btn.dataset.topic!==undefined){const d=LIBRARY[+btn.dataset.topic];if(d)showModal(`<div class="eyebrow">DISCOVERY LIBRARY / RESEARCH BRIEF</div><h2>${esc(d.icon)} ${esc(d.title)}</h2><p>${esc(d.desc)}</p><div class="family-note"><strong>TRY THIS FIRST:</strong> ${esc(d.topic)}</div><p>Use real books, verified references, or adult-approved tools for research. External content is not bundled.</p><button class="btn btn-primary" data-action="new-project" data-prefill="${esc(d.title+' discovery notes')}">${icon('plus')} START A NOTEBOOK</button>`);return}if(btn.dataset.filter){filter=btn.dataset.filter;render();return}if(btn.dataset.material){material=btn.dataset.material;erase=false;render();return}if(btn.dataset.prompt){void sendOrbit(btn.dataset.prompt);return}if(btn.dataset.action){const f=actions[btn.dataset.action];if(f)f(btn);return}});
document.addEventListener('submit',e=>{if(e.target.id==='chat-form'){e.preventDefault();const val=$('#chat-input').value.trim();if(val)void sendOrbit(val)}else if(e.target.id==='project-form'){e.preventDefault();saveProject(e.target)}else if(e.target.id==='journal-form'){e.preventDefault();saveJournal(e.target)}});
document.addEventListener('input',e=>{
 if(e.target.dataset.lab){const key=e.target.dataset.lab;if(!Object.prototype.hasOwnProperty.call(labState,key))return;labState[key]=key==='material'?e.target.value:Number(e.target.value);updateLabResults();clearTimeout(labSaveTimer);labSaveTimer=setTimeout(()=>store(profileKey('labs'),labState),350)}
 if(e.target.id==='guide-search'){
  const needle=e.target.value.trim().toLowerCase();
  $$('#guide-grid .guide-card').forEach(el=>el.hidden=needle.length>0&&!el.dataset.guideHaystack.includes(needle));
 }
});
document.addEventListener('change',e=>{if(e.target.id==='level-range'){layer=+e.target.value;render();return}if(e.target.id==='builder-import'){importBlueprint(e.target.files?.[0]);e.target.value='';return}if(e.target.id==='vault-import'){importVault(e.target.files?.[0]);e.target.value='';return}if(e.target.id==='journal-import'){void importJournal(e.target.files?.[0]);e.target.value='';return}if(e.target.id==='theme-choice'){appPrefs.theme=e.target.value;store(ns+'prefs',appPrefs);applyPrefs();notify('Atmosphere updated.')}if(e.target.id==='reduce-motion'){appPrefs.reducedMotion=e.target.checked;store(ns+'prefs',appPrefs);applyPrefs()}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();return}if(e.key==='Escape'){closeModal();closeSearch();$('#sidebar').classList.remove('open');$('#shade').hidden=true}if(!$('#command-overlay').hidden&&e.key==='Enter'){const first=$('#command-results [data-route]');if(first){e.preventDefault();go(first.dataset.route);closeSearch()}}});$('#command-input').addEventListener('input',drawSearch);$('#command-overlay').addEventListener('click',e=>{if(e.target.id==='command-overlay')closeSearch()});$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});$('#shade').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#shade').hidden=true});
async function bootstrap(){try{const r=await Promise.all([fetch('/data/quests.json'),fetch('/data/apps.json'),fetch('/data/learning.json')]);if(!r.every(x=>x.ok))throw Error('Missing local catalogs');quests=await r[0].json();apps=await r[1].json();lessons=await r[2].json();if(!Array.isArray(quests)||!Array.isArray(apps)||!Array.isArray(lessons))throw Error('Invalid catalogs')}catch(err){console.error('Local catalogs unavailable',err);quests=[];apps=[];lessons=[];notify('Start the included local Python server to load quests and apps.')}await wfInitSystem();await wfLoadPersistent();applyPrefs();appStart()}
bootstrap();
